import { Component, JSX, splitProps } from 'solid-js';
import * as FloatingDockPrimitive from '@exhuma/core';

export interface FloatingDockProps extends JSX.HTMLAttributes<HTMLDivElement> {
  [key: string]: unknown;
}

export const FloatingDock: Component<FloatingDockProps> = (props) => {
  const [local, others] = splitProps(props, ['class', 'children']);
  return (
    <FloatingDockPrimitive.FloatingDock
      class={`mx-auto flex h-16 items-end gap-3 rounded-2xl border border-border bg-card/80 px-4 pb-3 shadow-lg backdrop-blur-md ${local.class ?? ''}`}
      {...others}
    >
      {local.children}
    </FloatingDockPrimitive.FloatingDock>
  );
};

