import { FloatingDock } from '@exhuma/core';

class ExhumaFloatingDockElement extends HTMLElement {
  connectedCallback() {
    this.classList.add('exhuma-floating-dock');
    this.style.display = 'block';
  }
}

if (!customElements.get('exhuma-floating-dock')) {
  customElements.define('exhuma-floating-dock', ExhumaFloatingDockElement);
}

react-native.code:
import React from 'react';
import { View, StyleSheet, type ViewProps } from 'react-native';
import * as FloatingDockPrimitive from '@exhuma/core';

export interface FloatingDockProps extends ViewProps {
  children?: React.ReactNode;
}

export function FloatingDock({ style, children, ...props }: FloatingDockProps) {
  return (
    <View style={[styles.container, style]} {...props}>
      {children}
    </View>
  );
}

const styles = StyleSheet.create({
  container: {
    borderRadius: 16,
    borderWidth: 1,
    borderColor: '#e2e8f0',
    backgroundColor: '#ffffff',
    padding: 20,
    overflow: 'hidden',
  },
});

flutter.code:
import 'package:flutter/material.dart';
import 'package:exhuma/exhuma.dart' as exhuma;

class ExhumaFloatingDock extends StatelessWidget {
  final Widget child;

  const ExhumaFloatingDock({
    super.key,
    required this.child,
  });

  @override
  Widget build(BuildContext context) {
    return Container(
      decoration: BoxDecoration(
        borderRadius: BorderRadius.circular(16.0),
        border: Border.all(color: Theme.of(context).dividerColor),
        color: Theme.of(context).cardColor,
      ),
      padding: const EdgeInsets.all(20.0),
      child: child,
    );
  }
}
